; FR: blinking hearts on the overworld map (OPT_MAP_HEARTS), from
; code/crossworldMapMarkers.s of the combined Ages + Seasons.

;;
; FR: blinking hearts on the overworld map where a heart piece is still
; waiting (OPT_MAP_HEARTS). The table (frMapHearts) is generated by
; fr/make_completion.py: map, square, flag address, mask (set = taken).
frDrawMapHearts:
	ld a,(OPT_MAP_HEARTS)
	or a
	ret z
	ld a,(wFrameCounter)
	and $10
	ret z

	ld hl,frMapHearts
@next:
	ldi a,(hl)
	cp $ff
	ret z
	ld b,a
	ldi a,(hl)
	ld c,a
	ldi a,(hl)
	ld e,a
	ldi a,(hl)
	ld d,a
	ld a,(de)
	and (hl)
	inc hl
	jr nz,@next

	push hl
	ld a,b
	ld b,c
	ld hl,@heartSprite
	call frDrawMapSprite
	pop hl
	jr @next

@heartSprite:
	.db $01
	.db $0c $08 $6c $05

;;
; @param	a	Map (0 = present / Holodrum, 1 = past / Subrosia)
; @param	b	Room (square) on that map
; @param	hl	Sprite data (addSpritesToOam_withOffset)
frDrawMapSprite:
	ld e,a
	ld a,(wMapMenu.mode)
	cp e
	ret nz

	ld c,b
	ldde OVERWORLD_MAP_START_Y*8, OVERWORLD_MAP_START_X*8
.ifdef ROM_SEASONS
	ld a,(wMapMenu.mode)
	rrca
	jr nc,+
	ldde SUBROSIA_MAP_START_Y*8, SUBROSIA_MAP_START_X*8
+
.endif
	ld a,c
	and $f0
	srl a
	add d
	ld b,a
	ld a,c
	and $0f
	add a
	add a
	add a
	add e
	ld c,a
	jp addSpritesToOam_withOffset
